"""Portable HTML export with escaped evidence and no scripts or external assets."""
from html import escape
import base64
from report_data import summarize,chart_png,public_evidence,redact,test_inventory

def render(job):
    summary=summarize(job)
    esc=lambda value:escape(redact(value),quote=True)
    chart=base64.b64encode(chart_png(summary)).decode('ascii')
    overview='<h2>Executive summary</h2><p>'+str(summary['total'])+' unique automated candidates; '+str(len(summary['observations']))+' recon observations. Confidence: Unverified.</p><p>'+esc(summary['notice'])+'</p><img style="width:100%;max-width:800px" alt="Candidate distribution pie chart" src="data:image/png;base64,'+chart+'"><table><tr><th>Category</th><th>Count</th><th>Share</th></tr>'+''.join('<tr><td>'+esc(r['category'])+'</td><td>'+str(r['count'])+'</td><td>'+format(r['percent'],'.1f')+'%</td></tr>' for r in summary['distribution'])+'</table>'
    ledger=test_inventory(job)
    tests='<h2>Tests performed</h2><p>'+esc(ledger['notice'])+'</p><p>'+str(ledger['attempts'])+' command attempts; '+str(ledger['completed'])+' completed; '+str(ledger['failed'])+' failed or interrupted.</p><table><tr><th>Tool and test</th><th>Attempts</th><th>OK</th><th>Failed</th><th>Candidates</th><th>Status</th></tr>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in [r['tool']+' — '+r['test'],r['attempts'],r['completed'],r['failed'],r['candidates'],r['state']])+'</tr>' for r in ledger['rows'])+'</table>'
    stages=''.join('<tr><td>'+esc(s['name'])+'</td><td>'+esc(s['status'])+'</td><td>'+esc(s.get('detail',''))+'</td></tr>' for s in job.get('stages',[]))
    findings=''.join('<article><h2>'+esc(f['title'])+'</h2><p>'+esc(f['tool'])+' · '+esc(f['severity'])+'</p><p>'+esc(f['url'])+'</p><pre>'+esc(public_evidence(f))+'</pre><p>'+esc(f.get('recommendation',''))+'</p></article>' for f in summary['findings']+summary['observations'])
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pentest Lab Report</title><style>body{font:15px/1.7 Arial,sans-serif;max-width:960px;margin:50px auto;padding:0 24px;color:#25324b}h1,h2{font-weight:500}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #dde4ed;padding:12px}article{border:1px solid #dde4ed;padding:20px;margin:24px 0;border-radius:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7fb;padding:16px}p{overflow-wrap:anywhere}</style><h1>Pentest Lab Scan Report</h1>'''+f'<p><b>Version</b> {esc(job.get("version","Earlier version"))}<br><b>Target</b> {esc(job.get("target",""))}<br><b>Status</b> {esc(job["status"])}<br><b>Started</b> {esc(job["created"])}</p><p>Automated results require manual validation. Missing or incomplete checks do not establish that the target is secure.</p>{overview}{tests}<h2>Coverage</h2><p>Selected tools: {esc(", ".join(job.get("tools",[])))}</p><table><tr><th>Tool</th><th>Status</th><th>Detail</th></tr>{stages}</table><h2>Findings and observations</h2><p>{len(job.get("findings",[]))} results recorded.</p>{findings}<footer style="text-align:center;color:#64748b;margin-top:40px">Developed by Nowan</footer></html>'
